import { Controller, Get, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '인사 담당자';
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const ENROLL_INSURANCE = ['국민연금', '건강보험', '고용보험', '산재보험'];
const ENROLL_REPORT = ['취득', '상실'];
const REPORT_TYPES = ['QUALIFICATION_ACQUISITION', 'QUALIFICATION_LOSS', 'TOTAL_REMUNERATION', 'EMPLOYMENT_INDUSTRIAL', 'SEPARATION_CONFIRMATION', 'WORK_CONTENT_CONFIRMATION'];
const REPORT_INSURANCE = ['NATIONAL_PENSION', 'HEALTH', 'EMPLOYMENT', 'INDUSTRIAL_ACCIDENT'];
const INSURANCE_MAP: Record<string, string> = {
  '국민연금': 'NATIONAL_PENSION',
  '건강보험': 'HEALTH',
  '고용보험': 'EMPLOYMENT',
  '산재보험': 'INDUSTRIAL_ACCIDENT',
};

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function isBlank(v: unknown): boolean {
  return v === undefined || v === null || v === '';
}

function idOf(v: unknown, label: string): string {
  const n = Number(v);
  if (typeof v === 'boolean' || !Number.isInteger(n) || n <= 0) {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  return String(n);
}

function optId(v: unknown, label: string): string | null {
  return isBlank(v) ? null : idOf(v, label);
}

function optText(v: unknown, label: string, max: number, allowed?: string[]): string | null {
  if (isBlank(v)) {
    return null;
  }
  if (typeof v !== 'string' || v.length > max) {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  if (allowed && !allowed.includes(v)) {
    throw invalid(label + ' 값이 올바르지 않습니다.');
  }
  return v;
}

function optDate(v: unknown, label: string): string | null {
  if (isBlank(v)) {
    return null;
  }
  if (typeof v !== 'string' || !DATE_PATTERN.test(v)) {
    throw invalid(label + ' 형식이 올바르지 않습니다. (YYYY-MM-DD)');
  }
  return v;
}

function pagingOf(q: Record<string, unknown>): { page: number; size: number } {
  const page = isBlank(q['page']) ? 0 : Number(q['page']);
  const size = isBlank(q['size']) ? 20 : Number(q['size']);
  if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
    throw invalid('page 또는 size 형식이 올바르지 않습니다.');
  }
  return { page, size: Math.min(size, 200) };
}

@Controller('api/v1')
export class FnSfr02201Controller {
  @Post('/social-insurance-enrollments')
  @HttpCode(200)
  async createSocialInsuranceEnrollment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    if (isBlank(data['employeeId']) || isBlank(data['insuranceType']) || isBlank(data['reportType'])) {
      throw invalid('대상 임직원, 보험 종류, 신고 구분은 필수입니다.');
    }
    const employeeId = idOf(data['employeeId'], '임직원 ID');
    const insuranceType = optText(data['insuranceType'], '보험 종류', 50, ENROLL_INSURANCE);
    const reportType = optText(data['reportType'], '신고 구분', 50, ENROLL_REPORT);
    const acquisitionDate = optDate(data['acquisitionDate'], '취득일');
    const lossDate = optDate(data['lossDate'], '상실일');
    const lossReason = optText(data['lossReason'], '상실 사유', 500);
    if (reportType === '취득' && (acquisitionDate === null || lossReason !== null)) {
      throw new ApiError(422, 'ENROLLMENT_DATE_REQUIRED', '취득 신고에는 취득일이 필요하며 상실 사유는 입력할 수 없습니다.');
    }
    if (reportType === '상실' && (lossDate === null || lossReason === null)) {
      throw new ApiError(422, 'ENROLLMENT_DATE_REQUIRED', '상실 신고에는 상실일과 상실 사유가 필요합니다.');
    }
    return transaction(async (db) => {
      const records = await db.query(
        'SELECT personnel_record_id FROM personnel_record WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId },
      );
      if (records.length === 0) {
        throw new ApiError(404, 'PERSONNEL_RECORD_NOT_FOUND', '대상 임직원의 인사기록카드가 없습니다.');
      }
      const dup = await db.query(
        'SELECT social_insurance_enrollment_id FROM social_insurance_enrollment WHERE employee_id = CAST(:employeeId AS bigint) AND insurance_type = :insuranceType AND report_type = :reportType',
        { employeeId, insuranceType, reportType },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'ENROLLMENT_DUPLICATED', '이미 등록된 대상자·신고 구분입니다.');
      }
      const rows = await db.query(
        'INSERT INTO social_insurance_enrollment (employee_id, insurance_type, report_type, acquisition_date, loss_date, loss_reason, created_at, updated_at) VALUES (CAST(:employeeId AS bigint), :insuranceType, :reportType, CAST(:acquisitionDate AS date), CAST(:lossDate AS date), :lossReason, now(), now()) RETURNING social_insurance_enrollment_id AS "socialInsuranceEnrollmentId"',
        { employeeId, insuranceType, reportType, acquisitionDate, lossDate, lossReason },
      );
      return rows[0];
    });
  }

  @Get('/social-insurance-enrollments')
  async listSocialInsuranceEnrollments(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const { page, size } = pagingOf(q);
    const params = {
      employeeId: optId(q['employeeId'], '임직원 ID'),
      reportType: optText(q['reportType'], '신고 구분', 50, ENROLL_REPORT),
      insuranceType: optText(q['insuranceType'], '보험 종류', 50, ENROLL_INSURANCE),
    };
    const where = '(CAST(:employeeId AS bigint) IS NULL OR employee_id = CAST(:employeeId AS bigint)) AND (CAST(:reportType AS text) IS NULL OR report_type = CAST(:reportType AS text)) AND (CAST(:insuranceType AS text) IS NULL OR insurance_type = CAST(:insuranceType AS text))';
    return transaction(async (db) => {
      const counts = await db.query('SELECT COUNT(*) AS "total" FROM social_insurance_enrollment WHERE ' + where, params);
      const items = await db.query(
        'SELECT social_insurance_enrollment_id AS "socialInsuranceEnrollmentId", employee_id AS "employeeId", insurance_type AS "insuranceType", report_type AS "reportType", acquisition_date AS "acquisitionDate", loss_date AS "lossDate", loss_reason AS "lossReason" FROM social_insurance_enrollment WHERE ' + where + ' ORDER BY social_insurance_enrollment_id DESC LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { ...params, size, offset: page * size },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/social-insurance-reports')
  @HttpCode(200)
  async createSocialInsuranceReport(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    if (isBlank(data['reportType'])) {
      throw invalid('신고서 종류는 필수입니다.');
    }
    const reportType = optText(data['reportType'], '신고서 종류', 30, REPORT_TYPES) as string;
    const enrollmentId = optId(data['socialInsuranceEnrollmentId'], '취득·상실 대상자 ID');
    let employeeId = optId(data['employeeId'], '대상 임직원');
    let insuranceType = optText(data['insuranceType'], '보험 종류', 30, REPORT_INSURANCE);
    const periodStart = optDate(data['periodStart'], '대상 기간 시작일');
    const periodEnd = optDate(data['periodEnd'], '대상 기간 종료일');
    let eventDate = optDate(data['eventDate'], '취득일 또는 상실일');
    let lossReason = optText(data['lossReason'], '상실 사유', 200);
    let totalAmount: string | null = null;
    if (!isBlank(data['totalAmount'])) {
      const n = Number(data['totalAmount']);
      if (typeof data['totalAmount'] === 'boolean' || !Number.isFinite(n)) {
        throw invalid('보수총액은 숫자여야 합니다.');
      }
      totalAmount = String(n);
    }
    const isQualification = reportType === 'QUALIFICATION_ACQUISITION' || reportType === 'QUALIFICATION_LOSS';
    if (reportType !== 'QUALIFICATION_LOSS') {
      lossReason = null;
    }
    if (periodStart !== null && periodEnd !== null && periodEnd < periodStart) {
      throw invalid('대상 기간 종료일은 시작일 이후여야 합니다.');
    }
    return transaction(async (db) => {
      if (isQualification && enrollmentId === null) {
        throw new ApiError(404, 'ENROLLMENT_NOT_FOUND', '등록된 대상자가 없습니다.');
      }
      if (enrollmentId !== null) {
        const enrolls = await db.query(
          'SELECT employee_id AS "employeeId", insurance_type AS "insuranceType", acquisition_date AS "acquisitionDate", loss_date AS "lossDate", loss_reason AS "lossReason", report_type AS "reportType" FROM social_insurance_enrollment WHERE social_insurance_enrollment_id = CAST(:enrollmentId AS bigint)',
          { enrollmentId },
        );
        if (enrolls.length === 0) {
          throw new ApiError(404, 'ENROLLMENT_NOT_FOUND', '등록된 대상자가 없습니다.');
        }
        const en = enrolls[0];
        if (employeeId === null) {
          employeeId = String(en['employeeId']);
        }
        if (insuranceType === null) {
          insuranceType = INSURANCE_MAP[String(en['insuranceType'])] ?? null;
        }
        if (eventDate === null && isQualification) {
          const d = reportType === 'QUALIFICATION_ACQUISITION' ? en['acquisitionDate'] : en['lossDate'];
          eventDate = d === null || d === undefined ? null : String(d).slice(0, 10);
        }
        if (lossReason === null && reportType === 'QUALIFICATION_LOSS' && en['lossReason']) {
          lossReason = String(en['lossReason']).slice(0, 200);
        }
      }
      if (!isQualification && (periodStart === null || periodEnd === null)) {
        throw new ApiError(422, 'REPORT_DATA_NOT_FOUND', '신고서 대상 기간이 필요합니다.');
      }
      if (isQualification && (eventDate === null || (reportType === 'QUALIFICATION_LOSS' && lossReason === null))) {
        throw new ApiError(422, 'REPORT_DATA_NOT_FOUND', '신고서에 반영할 취득일·상실일 또는 상실 사유가 없습니다.');
      }
      let residentNumberEnc: string | null = null;
      if (employeeId !== null) {
        const people = await db.query(
          'SELECT resident_number_enc AS "residentNumberEnc" FROM personnel_record WHERE employee_id = CAST(:employeeId AS bigint)',
          { employeeId },
        );
        if (people.length === 0) {
          throw new ApiError(422, 'REPORT_DATA_NOT_FOUND', '대상 임직원의 인사 데이터가 없습니다.');
        }
        residentNumberEnc = (people[0]['residentNumberEnc'] as string | null) ?? null;
      }
      const rows = await db.query(
        'INSERT INTO social_insurance_report (employee_id, social_insurance_enrollment_id, report_type, insurance_type, period_start, period_end, event_date, loss_reason, total_amount, resident_number_enc, created_by_id, created_at, updated_at) VALUES (CAST(:employeeId AS bigint), CAST(:enrollmentId AS bigint), :reportType, :insuranceType, CAST(:periodStart AS date), CAST(:periodEnd AS date), CAST(:eventDate AS date), :lossReason, CAST(:totalAmount AS numeric), :residentNumberEnc, CAST(:userId AS bigint), now(), now()) RETURNING social_insurance_report_id AS "socialInsuranceReportId", created_at AS "createdAt"',
        { employeeId, enrollmentId, reportType, insuranceType, periodStart, periodEnd, eventDate, lossReason, totalAmount, residentNumberEnc, userId: user.id },
      );
      return rows[0];
    });
  }

  @Get('/social-insurance-reports')
  async listSocialInsuranceReports(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const { page, size } = pagingOf(q);
    const params = {
      employeeId: optId(q['employeeId'], '대상 임직원'),
      reportType: optText(q['reportType'], '신고서 종류', 30, REPORT_TYPES),
      insuranceType: optText(q['insuranceType'], '보험 종류', 30, REPORT_INSURANCE),
    };
    const where = '(CAST(:employeeId AS bigint) IS NULL OR employee_id = CAST(:employeeId AS bigint)) AND (CAST(:reportType AS text) IS NULL OR report_type = CAST(:reportType AS text)) AND (CAST(:insuranceType AS text) IS NULL OR insurance_type = CAST(:insuranceType AS text))';
    return transaction(async (db) => {
      const counts = await db.query('SELECT COUNT(*) AS "total" FROM social_insurance_report WHERE ' + where, params);
      const items = await db.query(
        'SELECT social_insurance_report_id AS "socialInsuranceReportId", employee_id AS "employeeId", report_type AS "reportType", insurance_type AS "insuranceType", event_date AS "eventDate", created_by_id AS "createdById", printed_at AS "printedAt", created_at AS "createdAt" FROM social_insurance_report WHERE ' + where + ' ORDER BY social_insurance_report_id DESC LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { ...params, size, offset: page * size },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/social-insurance-reports/:socialInsuranceReportId/print')
  @HttpCode(200)
  async printSocialInsuranceReport(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const reportId = idOf(req.params['socialInsuranceReportId'], '신고서 ID');
    return transaction(async (db) => {
      const rows = await db.query(
        'UPDATE social_insurance_report SET printed_at = now(), updated_at = now() WHERE social_insurance_report_id = CAST(:reportId AS bigint) RETURNING printed_at AS "printedAt"',
        { reportId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'SOCIAL_INSURANCE_REPORT_NOT_FOUND', '신고서를 찾을 수 없습니다.');
      }
      return rows[0];
    });
  }
}

