import { useState } from 'react';
import { Badge, Band, DataTable, DateInput, DateText, Drawer, Field, Filters, Form, LookupSelect, NumberInput, Num, Pager, Pairs, RefName, Select, TextInput, call, useData } from '../kit';
import type { Page, PageProps, Row } from '../kit';

const ENROLL_INSURANCE: [string, string][] = [
  ['국민연금', '국민연금'],
  ['건강보험', '건강보험'],
  ['고용보험', '고용보험'],
  ['산재보험', '산재보험'],
];
const ENROLL_REPORT: [string, string][] = [
  ['취득', '취득'],
  ['상실', '상실'],
];
const REPORT_TYPES: [string, string][] = [
  ['QUALIFICATION_ACQUISITION', '자격취득신고서'],
  ['QUALIFICATION_LOSS', '자격상실신고서'],
  ['TOTAL_REMUNERATION', '보수총액신고서'],
  ['EMPLOYMENT_INDUSTRIAL', '고용·산재보험 신고서'],
  ['SEPARATION_CONFIRMATION', '이직확인서'],
  ['WORK_CONTENT_CONFIRMATION', '근로내용확인신고서'],
];
const REPORT_INSURANCE: [string, string][] = [
  ['NATIONAL_PENSION', '국민연금'],
  ['HEALTH', '건강보험'],
  ['EMPLOYMENT', '고용보험'],
  ['INDUSTRIAL_ACCIDENT', '산재보험'],
];

function nameOf(options: [string, string][], value: unknown): string {
  const found = options.find((o) => o[0] === value);
  return found ? found[1] : String(value ?? '');
}

export default function FnSfr02201Page({ role, notify }: PageProps) {
  const [tab, setTab] = useState<'enrollment' | 'report'>('enrollment');
  const [drawer, setDrawer] = useState<'' | 'enrollment' | 'report'>('');
  const [selected, setSelected] = useState<Row | null>(null);

  const [eFilter, setEFilter] = useState<Row>({ reportType: '', insuranceType: '' });
  const [eApplied, setEApplied] = useState<Row>({});
  const [ePage, setEPage] = useState(0);
  const [rFilter, setRFilter] = useState<Row>({ reportType: '', insuranceType: '' });
  const [rApplied, setRApplied] = useState<Row>({});
  const [rPage, setRPage] = useState(0);

  const [eForm, setEForm] = useState<Row>({});
  const [rForm, setRForm] = useState<Row>({});

  const enrollments = useData<Page>(
    () => call<Page>('GET', '/social-insurance-enrollments', role, undefined, { ...eApplied, page: ePage }),
    [eApplied, ePage, role],
  );
  const reports = useData<Page>(
    () => call<Page>('GET', '/social-insurance-reports', role, undefined, { ...rApplied, page: rPage }),
    [rApplied, rPage, role],
  );

  const setE = (key: string, v: unknown) => setEForm({ ...eForm, [key]: v });
  const setR = (key: string, v: unknown) => setRForm({ ...rForm, [key]: v });

  const submitEnrollment = async () => {
    if (!eForm['employeeId'] || !eForm['insuranceType'] || !eForm['reportType']) {
      throw new Error('임직원, 보험 종류, 신고 구분을 모두 입력해 주세요.');
    }
    if (eForm['reportType'] === '취득' && !eForm['acquisitionDate']) {
      throw new Error('취득 신고에는 취득일을 입력해 주세요.');
    }
    if (eForm['reportType'] === '상실' && (!eForm['lossDate'] || !eForm['lossReason'])) {
      throw new Error('상실 신고에는 상실일과 상실 사유를 입력해 주세요.');
    }
    const body: Row = {
      employeeId: eForm['employeeId'],
      insuranceType: eForm['insuranceType'],
      reportType: eForm['reportType'],
    };
    if (eForm['reportType'] === '취득') {
      body['acquisitionDate'] = eForm['acquisitionDate'];
    } else {
      body['lossDate'] = eForm['lossDate'];
      body['lossReason'] = eForm['lossReason'];
    }
    await call('POST', '/social-insurance-enrollments', role, body);
    notify('대상자를 등록했습니다.');
    setDrawer('');
    setEForm({});
    enrollments.reload();
  };

  const submitReport = async () => {
    if (!rForm['reportType']) {
      throw new Error('신고서 종류를 선택해 주세요.');
    }
    const body: Row = {};
    const keys = ['socialInsuranceEnrollmentId', 'employeeId', 'reportType', 'insuranceType', 'periodStart', 'periodEnd', 'eventDate', 'lossReason', 'totalAmount'];
    keys.forEach((k) => {
      if (rForm[k] !== undefined && rForm[k] !== '') {
        body[k] = rForm[k];
      }
    });
    await call('POST', '/social-insurance-reports', role, body);
    notify('신고서를 생성했습니다.');
    setDrawer('');
    setRForm({});
    reports.reload();
  };

  const printReport = async () => {
    if (!selected) {
      return;
    }
    const id = selected['socialInsuranceReportId'];
    await call('POST', `/social-insurance-reports/${id}/print`, role, {});
    notify('신고서를 출력 처리했습니다.');
    setSelected(null);
    reports.reload();
  };

  if (selected) {
    return (
      <div className="doc">
        <button className="ghost" onClick={() => setSelected(null)}>목록으로 돌아가기</button>
        <section className="box">
          <h2>신고서 내용</h2>
          <Pairs
            items={[
              ['대상 임직원', <RefName table="employee" role={role} value={selected['employeeId']} />],
              ['신고서 종류', nameOf(REPORT_TYPES, selected['reportType'])],
              ['보험 종류', nameOf(REPORT_INSURANCE, selected['insuranceType'])],
              ['취득일 또는 상실일', <DateText value={selected['eventDate']} />],
              ['작성자', <RefName table="employee" role={role} value={selected['createdById']} />],
              ['생성 일시', <DateText value={selected['createdAt']} time />],
              ['최종 출력 일시', <DateText value={selected['printedAt']} time />],
            ]}
          />
        </section>
        <section className="box">
          <h2>출력</h2>
          <Form onSubmit={printReport} submit="출력 처리" note="출력 처리하면 최종 출력 일시가 현재 시각으로 갱신됩니다." />
        </section>
      </div>
    );
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>사회보험 취득·상실 관리</h2>
        <button className={tab === 'enrollment' ? '' : 'ghost'} onClick={() => setTab('enrollment')}>취득·상실 대상자</button>
        <button className={tab === 'report' ? '' : 'ghost'} onClick={() => setTab('report')}>신고서 이력</button>
      </section>

      {tab === 'enrollment' && (
        <section className="box">
          <h2>취득·상실 대상자</h2>
          <Filters
            onSearch={() => {
              setEPage(0);
              setEApplied({ ...eFilter });
            }}
            onReset={() => {
              setEFilter({ reportType: '', insuranceType: '' });
              setEApplied({});
              setEPage(0);
            }}
          >
            <Field label="신고 구분">
              <Select value={eFilter['reportType']} onChange={(v) => setEFilter({ ...eFilter, reportType: v })} options={ENROLL_REPORT} placeholder="전체" />
            </Field>
            <Field label="보험 종류">
              <Select value={eFilter['insuranceType']} onChange={(v) => setEFilter({ ...eFilter, insuranceType: v })} options={ENROLL_INSURANCE} placeholder="전체" />
            </Field>
          </Filters>
          <Band total={enrollments.data?.total}>
            <button onClick={() => setDrawer('enrollment')}>대상자 등록</button>
          </Band>
          <DataTable
            columns={[
              { key: 'employeeId', label: '임직원 ID', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
              { key: 'insuranceType', label: '보험 종류' },
              { key: 'reportType', label: '신고 구분', render: (r) => <Badge value={r['reportType']} /> },
              { key: 'acquisitionDate', label: '취득일', render: (r) => <DateText value={r['acquisitionDate']} /> },
              { key: 'lossDate', label: '상실일', render: (r) => <DateText value={r['lossDate']} /> },
            ]}
            rows={enrollments.data?.items ?? []}
            empty="아직 등록한 대상자가 없습니다. 대상자 등록 버튼으로 시작해 주세요."
          />
          <Pager page={ePage} size={enrollments.data?.size ?? 20} total={enrollments.data?.total ?? 0} onPage={setEPage} />
        </section>
      )}

      {tab === 'report' && (
        <section className="box">
          <h2>신고서 이력</h2>
          <Filters
            onSearch={() => {
              setRPage(0);
              setRApplied({ ...rFilter });
            }}
            onReset={() => {
              setRFilter({ reportType: '', insuranceType: '' });
              setRApplied({});
              setRPage(0);
            }}
          >
            <Field label="신고서 종류">
              <Select value={rFilter['reportType']} onChange={(v) => setRFilter({ ...rFilter, reportType: v })} options={REPORT_TYPES} placeholder="전체" />
            </Field>
            <Field label="보험 종류">
              <Select value={rFilter['insuranceType']} onChange={(v) => setRFilter({ ...rFilter, insuranceType: v })} options={REPORT_INSURANCE} placeholder="전체" />
            </Field>
          </Filters>
          <Band total={reports.data?.total}>
            <button onClick={() => setDrawer('report')}>신고서 생성</button>
          </Band>
          <DataTable
            columns={[
              { key: 'employeeId', label: '대상 임직원', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
              { key: 'reportType', label: '신고서 종류', render: (r) => nameOf(REPORT_TYPES, r['reportType']) },
              { key: 'insuranceType', label: '보험 종류', render: (r) => nameOf(REPORT_INSURANCE, r['insuranceType']) },
              { key: 'eventDate', label: '취득일 또는 상실일', render: (r) => <DateText value={r['eventDate']} /> },
              { key: 'printedAt', label: '최종 출력 일시', render: (r) => <DateText value={r['printedAt']} time /> },
            ]}
            rows={reports.data?.items ?? []}
            onRowClick={(r) => setSelected(r)}
            empty="아직 생성한 신고서가 없습니다. 신고서 생성 버튼으로 시작해 주세요."
          />
          <Pager page={rPage} size={reports.data?.size ?? 20} total={reports.data?.total ?? 0} onPage={setRPage} />
        </section>
      )}

      {drawer === 'enrollment' && (
        <Drawer title="취득·상실 대상자 등록" onClose={() => setDrawer('')}>
          <Form onSubmit={submitEnrollment} submit="등록">
            <Field label="임직원 ID" required>
              <LookupSelect table="employee" role={role} value={eForm['employeeId']} onChange={(v) => setE('employeeId', v)} />
            </Field>
            <Field label="보험 종류" required>
              <Select value={eForm['insuranceType']} onChange={(v) => setE('insuranceType', v)} options={ENROLL_INSURANCE} />
            </Field>
            <Field label="신고 구분" required>
              <Select value={eForm['reportType']} onChange={(v) => setE('reportType', v)} options={ENROLL_REPORT} />
            </Field>
            {eForm['reportType'] === '취득' && (
              <Field label="취득일" required>
                <DateInput value={eForm['acquisitionDate']} onChange={(v) => setE('acquisitionDate', v)} />
              </Field>
            )}
            {eForm['reportType'] === '상실' && (
              <Field label="상실일" required>
                <DateInput value={eForm['lossDate']} onChange={(v) => setE('lossDate', v)} />
              </Field>
            )}
            {eForm['reportType'] === '상실' && (
              <Field label="상실 사유" required wide>
                <TextInput value={eForm['lossReason']} onChange={(v) => setE('lossReason', v)} multiline />
              </Field>
            )}
          </Form>
        </Drawer>
      )}

      {drawer === 'report' && (
        <Drawer title="신고서 생성" onClose={() => setDrawer('')}>
          <Form onSubmit={submitReport} submit="생성" note="대상자를 고르면 인사정보가 신고서에 자동 반영됩니다.">
            <Field label="신고서 종류" required>
              <Select value={rForm['reportType']} onChange={(v) => setR('reportType', v)} options={REPORT_TYPES} />
            </Field>
            <Field label="취득·상실 대상자">
              <LookupSelect table="social_insurance_enrollment" role={role} value={rForm['socialInsuranceEnrollmentId']} onChange={(v) => setR('socialInsuranceEnrollmentId', v)} />
            </Field>
            <Field label="대상 임직원">
              <LookupSelect table="employee" role={role} value={rForm['employeeId']} onChange={(v) => setR('employeeId', v)} />
            </Field>
            <Field label="보험 종류">
              <Select value={rForm['insuranceType']} onChange={(v) => setR('insuranceType', v)} options={REPORT_INSURANCE} />
            </Field>
            <Field label="대상 기간 시작일">
              <DateInput value={rForm['periodStart']} onChange={(v) => setR('periodStart', v)} />
            </Field>
            <Field label="대상 기간 종료일">
              <DateInput value={rForm['periodEnd']} onChange={(v) => setR('periodEnd', v)} />
            </Field>
            <Field label="취득일 또는 상실일">
              <DateInput value={rForm['eventDate']} onChange={(v) => setR('eventDate', v)} />
            </Field>
            {rForm['reportType'] === 'QUALIFICATION_LOSS' && (
              <Field label="상실 사유" wide>
                <TextInput value={rForm['lossReason']} onChange={(v) => setR('lossReason', v)} />
              </Field>
            )}
            <Field label="보수총액">
              <NumberInput value={rForm['totalAmount']} onChange={(v) => setR('totalAmount', v)} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
